package org.eclipse.jdt.internal.ui.wizards.buildpaths;

import org.eclipse.core.runtime.IPath;
import org.eclipse.jdt.launching.JavaRuntime;

public class LibrariesWorkbookPage {
    public boolean isOtherContainer(IPath path) {
        if (path == null)
            return false;
        String[] segments= path.segments();
        for (String seg : segments) {
            if (seg.contains(JavaRuntime.JRE_CONTAINER)) { // Uses constant, not literal "JRE_CONTAINER"
                return true;
            }
            if (seg.contains("SOME_OTHER_TEXT")) { // Different literal
                return true;
            }
        }
        return false;
    }
}
